
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_n12_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_n12", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.528833529320274e+00, -4.437878649448273e+00, -4.310342272120126e+00, -4.133468361996069e+00, -3.891961131244980e+00, -3.569327166110013e+00, -3.151245850988348e+00, -2.632925005087869e+00, -2.041395225677191e+00, -1.515511199753225e+00, -1.168764096802466e+00, -7.169334618744306e-01, -6.065413680615701e-01, -4.975368894906698e-01, -3.503563853300698e-01, -2.109973215334926e-01, -7.143586204430867e-02, -1.657996742346573e-02, -8.749701739244576e-03, -1.189904557810628e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


